                  g3 = (float)(p[9] + p[10] + p[11]) * k3, g4 = (float)(p[12] + p[13] + p[14]) * k3;
            t[2 * m] = ((g0 + g1) + 0.5f * g2) * 0.4f; t[2 * m + 1] = ((0.5f * g2 + g3) + g4) * 0.4f;
