static void ns_prep_init(void) {
    double T[9], s_ = 128.0 / 320.0;
    ns_f = fx * s_; ns_cx = (cx + 0.5) * s_ - 0.5; ns_cy = (cy + 0.5) * s_ - 0.5;
    for (int i = 0; i < 3; i++) for (int j = 0; j < 3; j++) { double a = 0; for (int k = 0; k < 3; k++) a += lc_Rs[3 * k + i] * lc_R5[3 * k + j]; ns_Rb[3 * i + j] = a; }
    m3tmul(R_bc, ns_Rb, T); m3mul(T, R_bc, ns_Rc);
    ns_sum0 = 0; ns_sum1 = 0; ns_cnt = 0;
}
static void ns_prep_rows(int v0, int v1) {
    const double *Rc = ns_Rc, f_ = ns_f, cx_ = ns_cx, cy_ = ns_cy;
    for (int v = v0; v < v1; v++)
        for (int u = 0; u < LC_W; u++) {
            double d[3] = {(u - cx_) / f_, (v - cy_) / f_, 1.0}, dk[3];
            for (int i = 0; i < 3; i++) dk[i] = Rc[i] * d[0] + Rc[3 + i] * d[1] + Rc[6 + i] * d[2];
            double z = dk[2] > 1e-3 ? dk[2] : 1e-3, uk = f_ * dk[0] / z + cx_, vk = f_ * dk[1] / z + cy_;
            int ok = uk >= -0.5 && uk <= LC_W - 0.5 && vk >= -0.5 && vk <= LC_H - 0.5 && dk[2] > 1e-3;
            float val = 0;
            if (ok) {
                double fu = floor(uk), fv = floor(vk), au = uk - fu, av = vk - fv;
                int x0 = (int)fu, y0 = (int)fv;
                for (int dy = 0; dy < 2; dy++) for (int dx = 0; dx < 2; dx++) {
                    int xx = x0 + dx, yy = y0 + dy;
                    if (xx < 0 || xx >= LC_W || yy < 0 || yy >= LC_H) continue;
                    val += (float)((dx ? au : 1 - au) * (dy ? av : 1 - av)) * lc_g5[yy * LC_W + xx];
                }
            }
            int p = v * LC_W + u;
            lc_x1[p] = val; lc_m[p] = (float)ok; lc_x0[p] = lc_g0[p];
            ns_sum0 += lc_x0[p]; ns_sum1 += val; ns_cnt += ok;
        }
}
